class ChatMLConverter:
    def __init__(self, system_prompt):
        self.system_prompt = system_prompt

    def convert_single(self, entry, language='en', user_query=None):
        content = entry.get(language, entry.get('en', ''))
        if not user_query:
            user_query = self._generate_query(entry)
        return {
            'messages': [
                {'role': 'system', 'content': self.system_prompt},
                {'role': 'user', 'content': user_query},
                {'role': 'assistant', 'content': content}
            ],
            'metadata': {
                'source': entry.get('source', ''),
                'original_id': entry.get('id', ''),
                'language': language
            }
        }

    def convert_batch(self, entries, language='en'):
        return [self.convert_single(e, language) for e in entries]
